
%%\ ASSIGNMENT: MATRIX-VECTOR MULTIPLICATION
% MATLAB computational-thread benchmarking
%
% Matrix sizes: 50 to 2000 (10 sizes)
% Thread settings: 1 to 10
%
% Outputs:
% 1. Execution time
% 2. Speedup
% 3. Parallel efficiency
% 4. Execution time plots
% 5. Speedup plots
% 6. Efficiency plots

clc;
clear;
close all;

%%\ 1. PARAMETERS

sizes = [50 100 200 400 600 800 1000 1200 1600 2000];

threads = 1:10;

numSizes = length(sizes);
numThreads = length(threads);

% Number of timing batches
numBatches = 5;

% Store results
results = zeros(numSizes,numThreads);

% Store individual timing measurements
allTimes = zeros(numSizes,numThreads,numBatches);

% Number of repetitions is adjusted according to matrix size
% Approximately 10 million matrix entries processed per batch
repetitions = max(3,round(1e7./(sizes.^2)));

%%\ 2. CHECK THREAD CONTROL

fprintf('\n============================================\n'); %[output:45e0dbe6]
fprintf(' MATRIX-VECTOR MULTIPLICATION BENCHMARK\n'); %[output:499e5f71]
fprintf('============================================\n'); %[output:0b90f520]

try %[output:group:4be3e165]
    originalThreads = maxNumCompThreads;
    fprintf('Original MATLAB thread setting: %d\n',originalThreads); %[output:986aa69a]
catch
    error('maxNumCompThreads is unavailable.');
end %[output:group:4be3e165]

fprintf('\nMatrix sizes: '); %[output:3e652a70]
fprintf('%d ',sizes); %[output:62ddea10]

fprintf('\nThread settings: '); %[output:44a3ac52]
fprintf('%d ',threads); %[output:0d587b4d]

fprintf('\n\nNumber of batches: %d\n',numBatches); %[output:6ccc4adb]

%%\ 3. LOOP OVER MATRIX SIZES

for s = 1:numSizes %[output:group:2b324103]

    n = sizes(s);

    fprintf('\n============================================\n'); %[output:63e65aaa] %[output:951a867f] %[output:472d8b2f] %[output:89201e89] %[output:232763f4] %[output:5e564d26] %[output:638a90d6] %[output:1a834718] %[output:55287d1f] %[output:458cc927]
    fprintf('MATRIX SIZE: %d x %d\n',n,n); %[output:9575d58e] %[output:7cf0f98f] %[output:78067b87] %[output:9a579eff] %[output:437fb3cb] %[output:473d64c9] %[output:7c2dc43a] %[output:00956b03] %[output:084a345c] %[output:08653b99]
    fprintf('============================================\n'); %[output:6d16a493] %[output:24be3cf7] %[output:3f487566] %[output:2ab8bd3b] %[output:53f95cd6] %[output:00758971] %[output:6b482c43] %[output:334a0d01] %[output:5c5bd13a] %[output:0cbf2bfb]

    fprintf('Repetitions per batch: %d\n',repetitions(s)); %[output:3d50728c] %[output:721e0877] %[output:4adb2d4c] %[output:5f8cd198] %[output:90309f9d] %[output:32c2a95d] %[output:50e66db7] %[output:72d4b712] %[output:4328d47f] %[output:53b853e2]

    %%\ GENERATE MATRIX AND VECTOR

    rng(42);

    A = rand(n,n);
    x = rand(n,1);

    %%\ REFERENCE SOLUTION

    b_reference = A*x;

    %%\ 4. LOOP OVER THREAD SETTINGS

    for k = 1:numThreads

        numThreadsNow = threads(k);

        % Set MATLAB computational thread count
        maxNumCompThreads(numThreadsNow);

        fprintf('\nTesting with %d threads...\n',numThreadsNow); %[output:459c6c55] %[output:2312244f] %[output:90c02515] %[output:31bcbb72] %[output:6e88f83a] %[output:9d3191e6] %[output:6b677957] %[output:50cf6031] %[output:33c84892] %[output:0e72db4e] %[output:8a6cef69] %[output:2743b916] %[output:68b4cb25] %[output:7df6071a] %[output:73ba8058] %[output:217e7ee9] %[output:8cf6cbcf] %[output:309c7a9b] %[output:7bfb40e7] %[output:7003be47] %[output:731b4e02] %[output:54118d5d] %[output:44ac27c6] %[output:330c7fc3] %[output:83264232] %[output:4b1daad7] %[output:55d07fd2] %[output:69ffea5d] %[output:1d714f50] %[output:23e8d581] %[output:61c7696b] %[output:7ed8a8d5] %[output:81b7bed1] %[output:462b6e9c] %[output:18a20825] %[output:53e80856] %[output:51c508a1] %[output:33b1bdc9] %[output:832447fe] %[output:095846c7] %[output:111a2439] %[output:0b256dee] %[output:13bd9b51] %[output:6851950b] %[output:741450c2] %[output:8c6361b4] %[output:517d80fc] %[output:6db78437] %[output:0f6bf719] %[output:2dd61b10] %[output:5aed8915] %[output:866724aa] %[output:9f54b808] %[output:3e082fd5] %[output:751bb25f] %[output:3e70c21c] %[output:962a0ea1] %[output:657d8a5c] %[output:2f8bb497] %[output:0b9a806f] %[output:5f587a90] %[output:2a2d70ad] %[output:50231c68] %[output:8b21012d] %[output:9ebc6cfa] %[output:7b4edca8] %[output:53821a7c] %[output:2321d516] %[output:463bb129] %[output:07203800] %[output:950ad95d] %[output:4cb39b7e] %[output:04e97481] %[output:937dadbc] %[output:08fdf751] %[output:0dfdff3b] %[output:65d6c2ba] %[output:8fdc1a0f] %[output:29376bca] %[output:67dad6d3] %[output:48d4fac4] %[output:287b2a3f] %[output:7bffafe4] %[output:32cfdc11] %[output:9f0e6d42] %[output:6fbea448] %[output:6cdcad0a] %[output:5cff1d7a] %[output:40d1eee7] %[output:80007ccc] %[output:0f7fd2b0] %[output:39812565] %[output:78fc2d75] %[output:48a88540] %[output:86ac6cc4] %[output:8dae23e1] %[output:71bcc911] %[output:4c219aa1] %[output:6b0bef9b] %[output:2b10845f]

        %%\ WARM-UP

        b = A*x;

        %%\ CHECK NUMERICAL ACCURACY

        errorValue = norm(b-b_reference,inf);

        if errorValue > 1e-10
            warning('Numerical result differs from reference.');
        end

        %%\ REPEATED TIMING

        for r = 1:numBatches

            tic;

            for rep = 1:repetitions(s)

                b = A*x;

            end

            elapsedTime = toc;

            allTimes(s,k,r) = elapsedTime/repetitions(s);

        end

        %%\ MEDIAN EXECUTION TIME

        results(s,k) = median(squeeze(allTimes(s,k,:)));

        fprintf('Threads: %2d | Median time: %.10e seconds\n', ... %[output:6ef1a884] %[output:88d70f8f] %[output:79ce994e] %[output:144bbe15] %[output:913831ec] %[output:006ae747] %[output:67b05b53] %[output:30756668] %[output:6597e639] %[output:9bf55c83] %[output:25effd31] %[output:10a29dd8] %[output:2143d222] %[output:723ea6cf] %[output:0ec25ffd] %[output:93d2b78e] %[output:927f00b3] %[output:102dac87] %[output:3bb1592a] %[output:8782dcec] %[output:8c784a65] %[output:7292c348] %[output:37cc3108] %[output:8d45997a] %[output:6d0bd6b5] %[output:643ee762] %[output:65db4c0b] %[output:7053edd1] %[output:8b087a79] %[output:65b70f8e] %[output:6e6e173f] %[output:6a1ccdcf] %[output:16a1ab7f] %[output:8512b367] %[output:2e20651b] %[output:17cc7261] %[output:0ed18d86] %[output:4504f62e] %[output:7bc9881f] %[output:2c50b7f7] %[output:3934160b] %[output:184bf085] %[output:69153576] %[output:28f1af1e] %[output:359c590c] %[output:6a10327c] %[output:7d390dc9] %[output:7576fc37] %[output:08121a23] %[output:083de9db] %[output:8f8798d8] %[output:29a999c5] %[output:91bffda7] %[output:0991f5da] %[output:26a3e399] %[output:30d826a2] %[output:64a561df] %[output:347dd699] %[output:89c48d67] %[output:3c7da7c8] %[output:916f56ea] %[output:85a64965] %[output:128f1e03] %[output:03b46ca2] %[output:513784b4] %[output:18e5f718] %[output:59f53557] %[output:0428b7ad] %[output:90648857] %[output:9d0284c4] %[output:4c84287e] %[output:8bd10cc9] %[output:93a8c1b0] %[output:83145935] %[output:35f03aba] %[output:4620fc7f] %[output:46028787] %[output:5e0e5e56] %[output:97064a77] %[output:215d73a0] %[output:7fd4524a] %[output:16292e59] %[output:9cfa1d47] %[output:5eead350] %[output:83d57ed0] %[output:5e38c9d9] %[output:2f953d60] %[output:420e7d4f] %[output:649322fd] %[output:66110be9] %[output:265055ff] %[output:88810a21] %[output:0796501e] %[output:05757ece] %[output:0c0684fe] %[output:29cc4488] %[output:5d2ec2f9] %[output:54a75043] %[output:6f7f2a16] %[output:00fefd6b]
            numThreadsNow,results(s,k)); %[output:6ef1a884] %[output:88d70f8f] %[output:79ce994e] %[output:144bbe15] %[output:913831ec] %[output:006ae747] %[output:67b05b53] %[output:30756668] %[output:6597e639] %[output:9bf55c83] %[output:25effd31] %[output:10a29dd8] %[output:2143d222] %[output:723ea6cf] %[output:0ec25ffd] %[output:93d2b78e] %[output:927f00b3] %[output:102dac87] %[output:3bb1592a] %[output:8782dcec] %[output:8c784a65] %[output:7292c348] %[output:37cc3108] %[output:8d45997a] %[output:6d0bd6b5] %[output:643ee762] %[output:65db4c0b] %[output:7053edd1] %[output:8b087a79] %[output:65b70f8e] %[output:6e6e173f] %[output:6a1ccdcf] %[output:16a1ab7f] %[output:8512b367] %[output:2e20651b] %[output:17cc7261] %[output:0ed18d86] %[output:4504f62e] %[output:7bc9881f] %[output:2c50b7f7] %[output:3934160b] %[output:184bf085] %[output:69153576] %[output:28f1af1e] %[output:359c590c] %[output:6a10327c] %[output:7d390dc9] %[output:7576fc37] %[output:08121a23] %[output:083de9db] %[output:8f8798d8] %[output:29a999c5] %[output:91bffda7] %[output:0991f5da] %[output:26a3e399] %[output:30d826a2] %[output:64a561df] %[output:347dd699] %[output:89c48d67] %[output:3c7da7c8] %[output:916f56ea] %[output:85a64965] %[output:128f1e03] %[output:03b46ca2] %[output:513784b4] %[output:18e5f718] %[output:59f53557] %[output:0428b7ad] %[output:90648857] %[output:9d0284c4] %[output:4c84287e] %[output:8bd10cc9] %[output:93a8c1b0] %[output:83145935] %[output:35f03aba] %[output:4620fc7f] %[output:46028787] %[output:5e0e5e56] %[output:97064a77] %[output:215d73a0] %[output:7fd4524a] %[output:16292e59] %[output:9cfa1d47] %[output:5eead350] %[output:83d57ed0] %[output:5e38c9d9] %[output:2f953d60] %[output:420e7d4f] %[output:649322fd] %[output:66110be9] %[output:265055ff] %[output:88810a21] %[output:0796501e] %[output:05757ece] %[output:0c0684fe] %[output:29cc4488] %[output:5d2ec2f9] %[output:54a75043] %[output:6f7f2a16] %[output:00fefd6b]

    end

    clear A x b b_reference;

end %[output:group:2b324103]

%%\ 5. CALCULATE SPEEDUP AND EFFICIENCY

speedup = zeros(numSizes,numThreads);
efficiency = zeros(numSizes,numThreads);

for s = 1:numSizes

    for k = 1:numThreads

        % Speedup = T1 / Tp
        speedup(s,k) = results(s,1)/results(s,k);

        % Efficiency = Speedup / Number of threads
        efficiency(s,k) = speedup(s,k)/threads(k);

    end

end

%%\ 6. EXECUTION TIME TABLE

fprintf('\n\n========== EXECUTION TIME (SECONDS) ==========\n'); %[output:7232f9ed]

variableNames = cell(1,numThreads);

for k = 1:numThreads
    variableNames{k} = sprintf('T%d',threads(k));
end

rowNames = cell(1,numSizes);

for s = 1:numSizes
    rowNames{s} = sprintf('N%d',sizes(s));
end

TimeTable = array2table(results, ...
    'VariableNames',variableNames, ...
    'RowNames',rowNames);

disp(TimeTable); %[output:59d547b8]

%%\ 7. SPEEDUP TABLE

fprintf('\n========== SPEEDUP ==========\n'); %[output:517656a2]

SpeedupTable = array2table(speedup, ...
    'VariableNames',variableNames, ...
    'RowNames',rowNames);

disp(SpeedupTable); %[output:3ff57d19]

%%\ 8. PARALLEL EFFICIENCY TABLE

fprintf('\n========== PARALLEL EFFICIENCY ==========\n'); %[output:15f93ad7]

EfficiencyTable = array2table(efficiency, ...
    'VariableNames',variableNames, ...
    'RowNames',rowNames);

disp(EfficiencyTable); %[output:5976f552]

%%\ 9. EXECUTION TIME PLOT

figure(1); %[output:4e0567b7]

for s = 1:numSizes

    subplot(2,5,s); %[output:4e0567b7]

    plot(threads,results(s,:),'-o', ...
        'LineWidth',1.3,'MarkerSize',5);

    xlabel('Number of Threads');
    ylabel('Time (s)');

    title(sprintf('%d x %d',sizes(s),sizes(s)));

    xticks(threads);
    grid on;
    box on;

end

sgtitle('Execution Time vs Number of Threads'); %[output:4e0567b7]

%%\ 10. SPEEDUP PLOT

figure(2); %[output:3ab21996]

for s = 1:numSizes

    subplot(2,5,s); %[output:3ab21996]

    plot(threads,speedup(s,:),'-o', ...
        'LineWidth',1.3,'MarkerSize',5);

    hold on;

    % Ideal speedup
    plot(threads,threads,'--k','LineWidth',1);

    xlabel('Number of Threads');
    ylabel('Speedup');

    title(sprintf('%d x %d',sizes(s),sizes(s)));

    xticks(threads);
    grid on;
    box on;

end

sgtitle('Speedup vs Number of Threads'); %[output:3ab21996]

%%\ 11. PARALLEL EFFICIENCY PLOT

figure(3); %[output:9bdf3c3d]

for s = 1:numSizes

    subplot(2,5,s); %[output:9bdf3c3d]

    plot(threads,efficiency(s,:),'-o', ...
        'LineWidth',1.3,'MarkerSize',5);

    hold on;

    yline(1,'--k','Ideal Efficiency');

    xlabel('Number of Threads');
    ylabel('Efficiency');

    title(sprintf('%d x %d',sizes(s),sizes(s)));

    xticks(threads);
    grid on;
    box on;

end

sgtitle('Parallel Efficiency vs Number of Threads'); %[output:9bdf3c3d]

%%\ 12. EXECUTION TIME COMPARISON

figure(4); %[output:8befeb9f]

plot(threads,results','-o','LineWidth',1.3); %[output:8befeb9f]

xlabel('Number of Threads'); %[output:8befeb9f]
ylabel('Execution Time (seconds)'); %[output:8befeb9f]

title('Execution Time Comparison for Different Matrix Sizes'); %[output:8befeb9f]

legend(rowNames,'Location','bestoutside'); %[output:8befeb9f]

xticks(threads); %[output:8befeb9f]
grid on; %[output:8befeb9f]
box on; %[output:8befeb9f]

%%\ 13. SPEEDUP COMPARISON

figure(5); %[output:90eafd44]

plot(threads,speedup','-o','LineWidth',1.3); %[output:90eafd44]

hold on; %[output:90eafd44]

plot(threads,threads,'--k','LineWidth',1.5); %[output:90eafd44]

xlabel('Number of Threads'); %[output:90eafd44]
ylabel('Speedup'); %[output:90eafd44]

title('Speedup Comparison for Different Matrix Sizes'); %[output:90eafd44]

legend([rowNames,{'Ideal Speedup'}],'Location','bestoutside'); %[output:90eafd44]

xticks(threads); %[output:90eafd44]
grid on; %[output:90eafd44]
box on; %[output:90eafd44]

%%\ 14. RESTORE ORIGINAL THREAD SETTING

maxNumCompThreads(originalThreads);

fprintf('\n============================================\n'); %[output:9be03459]
fprintf('BENCHMARK COMPLETED SUCCESSFULLY\n'); %[output:0aee67e2]
fprintf('============================================\n'); %[output:7bf1b451]
